const __pageData = JSON.parse('{"title":"Congress","description":"","frontmatter":{"title":"Congress","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["government","legislature","free-speech","antisemitism","lobbying","appropriations"],"sources":["raw/a-glaring-double-standard.md","raw/a-conflict-of-interest.md","raw/americas-greatest-threat.md","raw/bad-actors.md","raw/badlands-brief-07c.md","raw/badlands-brief-094.md","raw/badlands-brief-05f.md","raw/badlands-brief-169.md","raw/badlands-brief-1ae.md","raw/badlands-brief-1c6.md","raw/badlands-brief-311.md","raw/badlands-brief-40d.md","raw/badlands-brief-52f.md","raw/badlands-brief-733.md","raw/badlands-brief-708.md","raw/badlands-brief-8c2.md","raw/badlands-brief-9ac.md","raw/badlands-brief-9ea.md","raw/badlands-brief-e60.md","raw/badlands-brief-f62.md","raw/badlands-news-brief-017.md","raw/badlands-news-brief-051.md","raw/badlands-news-brief-0b0.md","raw/badlands-news-brief-0f0.md","raw/badlands-news-brief-10a.md","raw/badlands-news-brief-116.md","raw/badlands-news-brief-169.md","raw/badlands-news-brief-1a0.md","raw/badlands-news-brief-25f.md","raw/badlands-news-brief-362.md","raw/badlands-news-brief-357.md","raw/badlands-news-brief-71f.md","raw/badlands-news-brief-7ad.md","raw/badlands-news-brief-762.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/congress.md","filePath":"entities/congress.md","lastUpdated":null}');
